export const CollapseableText = ({
  text,
  state = 'collapse',
  minWidth = 200,
  maxWidth = 600,
  isMultiLine = false,
  lineHeightPrefix = '',
  ...props
}) => {
  // Handle edge cases
  if (!text || text.trim() === '') {
    return null;
  }

  // Initialize state based on props
  const initialExpanded = state === 'open';
  const [isExpanded, setIsExpanded] = useState(initialExpanded);

  // Recalculate state on text changes
  useEffect(() => {
    if (isMultiLine) {
      setIsExpanded(false); // Auto-collapse when text becomes multi-line
    } else {
      if (isExpanded && !isMultiLine) {
        // Show the full collapsed text (only first line) when switching to one-line text
        setIsExpanded(false);
      }
      if (!isExpanded && isMultiLine) {
        // Show full text when switching to multi-line
        setIsExpanded(true);
      }
      setIsExpanded(initialExpanded); // Reset based on initial state
