## My answer to the prompt

A reliable way to keep “See more” visible at the end of the first line is to put the truncated text and the link side by side. Measure the full text separately to determine whether it overflows; otherwise, `numberOfLines={1}` can make the overflow check report only the displayed line.

```jsx
import React, { useEffect, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

export default function ExpandableText({
  text,
  style,
  textStyle,
  linkStyle,
  moreLabel = 'See more',
}) {
  const [width, setWidth] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setHasMore(false);
    setExpanded(false);
  }, [text]);

  const handleLayout = (event) => {
    const nextWidth = event.nativeEvent.layout.width;
    setWidth((current) => (current === nextWidth ? current : nextWidth));
  };

  const handleMeasure = (event) => {
    const nextHasMore = event.nativeEvent.lines.length > 1;
    setHasMore((current) => (current === nextHasMore ? current : nextHasMore));
  };

  return (
    <View style={style} onLayout={handleLayout}>
      {width > 0 && (
        <Text
          accessible={false}
          importantForAccessibility="no-hide-descendants"
          pointerEvents="none"
          onTextLayout={handleMeasure}
          style={[styles.text, textStyle, styles.measurement, { width }]}
        >
          {text}
        </Text>
      )}

      {expanded ? (
        <Text style={[styles.text, textStyle]}>{text}</Text>
      ) : (
        <View style={styles.row}>
          <Text
            numberOfLines={1}
            ellipsizeMode="tail"
            style={[styles.text, textStyle, styles.truncatedText]}
          >
            {text}
          </Text>

          {hasMore && (
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={moreLabel}
              onPress={() => setExpanded(true)}
            >
              <Text style={[styles.text, styles.link, linkStyle]}>
                {moreLabel}
              </Text>
            </Pressable>
          )}
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  text: {
    fontSize: 16,
    color: '#333',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'baseline',
  },
  truncatedText: {
    flex: 1,
    flexShrink: 1,
    minWidth: 0,
  },
  link: {
    color: '#007AFF',
  },
  measurement: {
    position: 'absolute',
    top: 0,
    left: 0,
    opacity: 0,
  },
});
```

Usage:

```jsx
